import{_ as s,o as n,c as t,a0 as e}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"Math.min()","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/Math/min.md","filePath":"jsApi/Math/min.md","lastUpdated":1791573371000}'),l={name:"jsApi/Math/min.md"};function p(i,a,o,r,c,d){return n(),t("div",null,[...a[0]||(a[0]=[e(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Math/min" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Math/min" target="_blank">en</a></p><h1 id="math-min" tabindex="-1">Math.min() <a class="header-anchor" href="#math-min" aria-label="Permalink to &quot;Math.min()&quot;">​</a></h1><p>Math.min() 返回零个或更多个数值的最小值。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Math.</span><span style="color:#6F42C1;">min</span><span style="color:#24292E;">([value1[,value2, </span><span style="color:#D73A49;">...</span><span style="color:#24292E;">]])</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><ul><li><code>value1, value2, ...</code> 一组数值</li></ul><h3 id="返回值" tabindex="-1">返回值 <a class="header-anchor" href="#返回值" aria-label="Permalink to &quot;返回值&quot;">​</a></h3><p>给定数值中最小的数。如果任一参数不能转换为数值，则返回NaN。</p><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>由于 min 是 Math 的静态方法，所以应该像这样使用：Math.min()，而不是作为你创建的 Math 实例的方法（Math 不是构造函数）。</p><p>如果没有参数，结果为Infinity。</p><p>如果有任一参数不能被转换为数值，结果为 NaN。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="使用-math-min" tabindex="-1">使用 Math.min() <a class="header-anchor" href="#使用-math-min" aria-label="Permalink to &quot;使用 Math.min()&quot;">​</a></h3><p>下例找出 x 和 y 的最小值，并把它赋值给 z：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> x </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 10</span><span style="color:#24292E;">, y </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> -</span><span style="color:#005CC5;">20</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> z </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> Math.</span><span style="color:#6F42C1;">min</span><span style="color:#24292E;">(x, y);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="使用-math-min-裁剪值-clipping-a-value" tabindex="-1">使用 Math.min() 裁剪值（Clipping a value） <a class="header-anchor" href="#使用-math-min-裁剪值-clipping-a-value" aria-label="Permalink to &quot;使用 Math.min() 裁剪值（Clipping a value）&quot;">​</a></h3><p>Math.min 经常用于裁剪一个值，以便使其总是小于或等于某个边界值。例如：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> x </span><span style="color:#D73A49;">=</span><span style="color:#6F42C1;"> f</span><span style="color:#24292E;">(foo);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">if</span><span style="color:#24292E;"> (x </span><span style="color:#D73A49;">&gt;</span><span style="color:#24292E;"> boundary) {</span></span>
<span class="line"><span style="color:#24292E;">    x </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> boundary;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>可以写成：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> x </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> Math.</span><span style="color:#6F42C1;">min</span><span style="color:#24292E;">(</span><span style="color:#6F42C1;">f</span><span style="color:#24292E;">(foo), boundary);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>另外，Math.max() 也可以被用来以相似的方式裁剪一个值。</p><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 1rd Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table>`,25)])])}const m=s(l,[["render",p]]);export{b as __pageData,m as default};
